//! Passive Text children preserve native identity, records and live ranges.
use super::*;
fn fixture()->(Document,Forms,Page){let mut d=crate::html::parse_loaded_document_with_scripting("<head><title id=title>Original title</title></head><body><noscript id=host>held</noscript><button id=button>Caption</button><p id=from>Ordinary</p><p id=out>Real</p>",true,&||Ok(())).unwrap();let mut f=Forms::new(&d);let mut p=Page::new();let l=crate::navigation::address("https://replace-all-source-ancestry.test/",&crate::navigation::Location::home()).unwrap();p.set_location(&l);p.set_resource_base(&l);assert_eq!(p.start(&mut d,&mut f,&[]).errors,0);(d,f,p)}
fn run(d:&mut Document,f:&mut Forms,p:&mut Page,s:&str){p.runtime.execute(s,&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();}
fn refusal(d:&mut Document,f:&mut Forms,p:&mut Page,code:&str)->String{let source=format!("var caughtFailure=null;try{{{code}}}catch(e){{caughtFailure=e.name+': '+e.message;}}");match p.runtime.execute(&source,&mut Bridge{doc:d,forms:f,state:&mut p.state}){Err(e)=>e,Ok(_)=>{let value=p.runtime.execute("caughtFailure",&mut Bridge{doc:d,forms:f,state:&mut p.state}).unwrap();let Value::String(message)=value else{panic!("Expected an actual native refusal: {value:?}")};message}}}


fn guarded_source(id:&str){
 let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var source=document.getElementById('{id}'),text=source.firstChild,out=document.getElementById('out'),original=out.firstChild,oldText=text.data,range=document.createRange(),watch=new MutationObserver(function(){{}});range.setStart(text,1);range.setEnd(text,2);watch.observe(source,{{childList:true}});watch.observe(out,{{childList:true}});"));p.state.rebuild(&d).unwrap();let before=format!("{:?}",d.nodes);let commits=p.state.dom_commits;let title=d.title.clone();let values=f.controls.values().map(|c|c.value.text()).collect::<Vec<_>>();p.begin_job();let e=refusal(&mut d,&mut f,&mut p,"out.replaceChildren(text);");assert!(e.contains("inert resource subtrees"),"{e}");assert_eq!(format!("{:?}",d.nodes),before);assert_eq!(p.state.dom_commits,commits);assert_eq!(d.title,title);assert_eq!(f.controls.values().map(|c|c.value.text()).collect::<Vec<_>>(),values);p.begin_job();run(&mut d,&mut f,&mut p,"if(source.firstChild!==text||text.parentNode!==source||text.data!==oldText||out.firstChild!==original||range.startContainer!==text||range.endContainer!==text||range.startOffset!==1||range.endOffset!==2||watch.takeRecords().length)throw 'replace-all source guard prefix';out.textContent='Recovered';");assert!(p.take_dynamic_scripts().is_empty());assert!(p.take_dynamic_stylesheets().is_empty());
}
#[test]
fn replace_all_source_ancestry_loaded_button_text_removal_refuses_atomically_and_recovers(){guarded_source("button");}
#[test]
fn replace_all_source_ancestry_loaded_title_text_removal_refuses_atomically_and_recovers(){guarded_source("title");}
#[test]
fn replace_all_source_ancestry_ordinary_and_passive_text_transfers_keep_actual_records_and_ranges(){
 for id in ["from","host"]{let(mut d,mut f,mut p)=fixture();run(&mut d,&mut f,&mut p,&format!("var source=document.getElementById('{id}'),text=source.firstChild,out=document.getElementById('out'),original=out.firstChild,raw=text.data,watch=new MutationObserver(function(){{}}),range=document.createRange();range.setStart(text,1);range.setEnd(text,2);watch.observe(source,{{childList:true}});watch.observe(out,{{childList:true}});out.replaceChildren(text);var rs=watch.takeRecords();if(source.firstChild!==null||out.firstChild!==text||out.childNodes.length!==1||text.data!==raw||text.parentNode!==out||text.ownerDocument!==document||original.parentNode!==null||original.data!=='Real'||rs.length!==2||rs[0].target!==source||rs[0].removedNodes[0]!==text||rs[1].target!==out||rs[1].removedNodes[0]!==original||rs[1].addedNodes[0]!==text||range.startContainer!==source||range.endContainer!==source||range.startOffset||range.endOffset)throw 'actual checked source transfer';"));assert!(p.take_dynamic_scripts().is_empty());}
}
